:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #533483;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.75rem;
  color: var(--primary);
  letter-spacing: 1px;
}

.score {
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--secondary);
  padding: 8px 16px;
  border-radius: 8px;
}

.canvas-wrapper {
  position: relative;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-width: 400px;
  margin: 0 auto;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: #0a0a1a;
  border-radius: 8px;
  image-rendering: pixelated;
  border: 2px solid var(--secondary);
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  gap: 12px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, visibility 0.2s;
}

.overlay.visible {
  opacity: 1;
  visibility: visible;
}

.overlay h2 {
  color: var(--primary);
  font-size: 1.5rem;
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  max-width: 300px;
}

#overlayHint {
  color: #aaa;
  font-size: 0.9rem;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  background: var(--secondary);
  color: var(--text);
  border: 2px solid transparent;
  padding: 12px 24px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-width: 100px;
}

.btn:hover {
  background: var(--accent);
}

.btn:focus-visible {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

.btn:active {
  transform: scale(0.96);
  background: var(--primary);
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #ff5a7a;
}

.btn.primary:active {
  background: #c7304a;
}

.instructions {
  text-align: center;
  font-size: 0.9rem;
  color: #aaa;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .score {
    font-size: 1rem;
    padding: 6px 12px;
  }
  .btn {
    padding: 10px 16px;
    min-width: 80px;
    font-size: 0.9rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayHint = document.getElementById('overlayHint');
  const overlayButton = document.getElementById('overlayButton');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, food, direction, nextDirection, score, state, loopId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    state = 'paused';
    placeFood();
    draw();
    updateUI();
  }

  function placeFood() {
    const free = [];
    for (let x = 0; x < GRID; x++) {
      for (let y = 0; y < GRID; y++) {
        if (!snake.some(s => s.x === x && s.y === y)) free.push({ x, y });
      }
    }
    food = free[Math.floor(Math.random() * free.length)];
  }

  function draw() {
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#eaeaea' : '#533483';
      ctx.fillRect(seg.x * CELL, seg.y * CELL, CELL, CELL);
    });
  }

  function updateUI() {
    if (state === 'paused') {
      overlayTitle.textContent = 'How to Play';
      overlayText.textContent = 'Use arrow keys to move. Eat the red pixel to grow and score. Avoid walls and yourself.';
      overlayHint.textContent = 'Press Space or click Start to begin.';
      overlayButton.textContent = 'Start';
      overlayButton.setAttribute('aria-label', 'Start game');
      overlay.classList.add('visible');
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    } else if (state === 'running') {
      overlay.classList.remove('visible');
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    } else if (state === 'gameover') {
      overlayTitle.textContent = 'Game Over';
      overlayText.textContent = 'Final Score: ' + score;
      overlayHint.textContent = 'Press R or click Restart to play again.';
      overlayButton.textContent = 'Restart';
      overlayButton.setAttribute('aria-label', 'Restart game');
      overlay.classList.add('visible');
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    }
  }

  function togglePause() {
    if (state === 'gameover') return;
    if (state === 'running') {
      state = 'paused';
      clearInterval(loopId);
      loopId = null;
    } else {
      state = 'running';
      loopId = setInterval(tick, 150);
    }
    updateUI();
  }

  function restart() {
    clearInterval(loopId);
    loopId = null;
    init();
  }

  function tick() {
    direction = nextDirection;
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      state = 'gameover';
      clearInterval(loopId);
      loopId = null;
      updateUI();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function handleKey(e) {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }

    if (key === ' ') {
      togglePause();
      return;
    }

    if (key === 'r' || key === 'R') {
      restart();
      return;
    }

    if (state !== 'running') return;

    const dirs = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };

    const nd = dirs[key];
    if (!nd) return;
    if (nd.x === -direction.x && nd.y === -direction.y) return;
    nextDirection = nd;
  }

  overlayButton.addEventListener('click', () => {
    if (state === 'gameover') restart();
    else if (state === 'paused') togglePause();
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  document.addEventListener('keydown', handleKey);

  init();
})();
